import pytest
from parse_kv import parse_kv


def test_basic():
    assert parse_kv("a=1; b=2") == {"a": "1", "b": "2"}


def test_single():
    assert parse_kv("x=42") == {"x": "42"}


def test_empty():
    assert parse_kv("") == {}


def test_whitespace():
    assert parse_kv("  name = alice ;   age = 30  ") == {"name": "alice", "age": "30"}


def test_escaped_semicolon():
    # backslash-semicolon means literal ; inside the value
    result = parse_kv("a=1; b=hello\\;world; c=3")
    assert result == {"a": "1", "b": "hello;world", "c": "3"}


def test_multiple_escaped_semicolons():
    # Multiple escaped semicolons in one value
    result = parse_kv("msg=hello\\;world\\;test; other=value")
    assert result == {"msg": "hello;world;test", "other": "value"}


